// LENT : on cree un nouvel objet a chaque tour de boucle.
// Dans une boucle appelee des millions de fois (une "boucle chaude"),
// cela remplit le tas et declenche le GC tres souvent.
String resultat = "";
for (int i = 0; i < 1_000_000; i++) {
    resultat = resultat + i; // chaque + cree une nouvelle String
}

// RAPIDE : on reutilise un seul tampon au lieu d'allouer sans cesse.
// Beaucoup moins d'objets crees, donc beaucoup moins de pression GC.
StringBuilder tampon = new StringBuilder();
for (int i = 0; i < 1_000_000; i++) {
    tampon.append(i);
}
String resultat2 = tampon.toString();

// FUITE : cette Map statique ne fait que grandir.
// Rien ne retire jamais d'entree, donc le GC ne peut rien liberer.
static final Map<String, Utilisateur> cache = new HashMap<>();

Utilisateur charger(String id) {
    return cache.computeIfAbsent(id, cle -> lireEnBase(cle));
}

// CORRIGE : un cache borne qui evince les entrees les plus anciennes.
// Ici au plus 10 000 entrees ; au-dela, les plus vieilles sont retirees,
// donc le GC peut liberer leur memoire.
static final Map<String, Utilisateur> cache = new LinkedHashMap<>(16, 0.75f, true) {
    @Override
    protected boolean removeEldestEntry(Map.Entry<String, Utilisateur> plusAncienne) {
        return size() > 10_000;
    }
};
